package foodchain

import "strings"

var animals = []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

// comments holds the animal-specific comment line for each verse
// (1-based verse number), if one exists.
var comments = map[int]string{
	2: "It wriggled and jiggled and tickled inside her.",
	3: "How absurd to swallow a bird!",
	4: "Imagine that, to swallow a cat!",
	5: "What a hog, to swallow a dog!",
	6: "Just opened her throat and swallowed a goat!",
	7: "I don't know how she swallowed a cow!",
	8: "She's dead, of course!",
}

// catchers holds the modifier appended to an animal when it is
// referred to as the prey in a "She swallowed the X to catch the Y" line.
var catchers = map[int]string{
	1: " that wriggled and jiggled and tickled inside her",
}

// Verse returns the lyrics of verse v (1 = fly, 8 = horse).
func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a " + animals[v-1] + ".\n")
	if c, ok := comments[v]; ok {
		b.WriteString(c + "\n")
	}
	if v < 8 {
		for i := v - 1; i >= 1; i-- {
			b.WriteString("She swallowed the " + animals[i] + " to catch the " +
				animals[i-1] + catchers[i-1] + ".\n")
		}
		b.WriteString("I don't know why she swallowed the fly. Perhaps she'll die.\n")
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// Verses returns the lyrics of verses start through end, joined by blank lines.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, 8)
}
